test('vatSummary zero VAT rate included', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [
    { sku: 'ICON-SET', qty: 1 },
  ]);

  // Check if any line has 0 VAT rate by examining the invoice
  const hasZeroVat = invoice.lines.some((line) => line.vatRate === 0);
  const r = vatSummary([invoice]);

  // If invoice has a 0% VAT line, it should be in the summary
  if (hasZeroVat) {
    const zeroRateEntry = r.find((item) => item.rate === 0);
    if (zeroRateEntry) {
      assert(zeroRateEntry.base >= 0);
      assert.equal(zeroRateEntry.vat, 0);
    }
  }
});

