    assert(r[i].rate >= r[i + 1].rate);
  }
});

test('vatSummary with invoice having discount', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [
    { sku: 'ICON-SET', qty: 1, discountPercent: 10 },
  ]);

  const r = vatSummary([invoice]);
  assert.equal(r.length, 1);
  assert(r[0].base > 0);
  assert(r[0].vat > 0);
});

test('vatSummary with multiple VAT rates', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 2 }]);
  const invoice2 = createAndIssueInvoice('C-002', '2025-02-15', [{ sku: 'DES-HOUR', qty: 5 }]);

  const r = vatSummary([invoice1, invoice2]);
  assert(r.length > 0);
  const rates = r.map((item) => item.rate);
  const uniqueRates = new Set(rates);
  assert.equal(uniqueRates.size, r.length);
});

test('vatSummary includes rate in each entry', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const r = vatSummary([invoice]);
  assert.equal(r.length, 1);
  assert('rate' in r[0]);
  assert('base' in r[0]);
  assert('vat' in r[0]);
});

test('vatSummary with complex multi-line invoice', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [
    { sku: 'ICON-SET', qty: 2, discountPercent: 5 },
    { sku: 'DES-HOUR', qty: 1 },
    { sku: 'ICON-SET', qty: 3 },
  ]);

  const r = vatSummary([invoice]);
  assert(r.length > 0);
  for (const item of r) {
    assert(item.rate >= 0);
    assert(item.base >= 0);
    assert(item.vat >= 0);
  }
});

test('vatSummary with mixed invoice statuses', () => {
  const issued = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const invoiceForPayment = createAndIssueInvoice('C-001', '2025-02-15', [{ sku: 'DES-HOUR', qty: 1 }]);
  const partial = recordPayment(invoiceForPayment, { amount: 500, date: '2025-02-20' });

  const r = vatSummary([issued, partial.value]);
  assert(r.length > 0);
});

test('vatSummary zero VAT rate included', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [
    { sku: 'ICON-SET', qty: 1 },
  ]);

  // Check if any line has 0 VAT rate by examining the invoice
  const hasZeroVat = invoice.lines.some((line) => line.vatRate === 0);
  const r = vatSummary([invoice]);

  // If invoice has a 0% VAT line, it should be in the summary
  if (hasZeroVat) {
    const zeroRateEntry = r.find((item) => item.rate === 0);
    if (zeroRateEntry) {
      assert(zeroRateEntry.base >= 0);
      assert.equal(zeroRateEntry.vat, 0);
    }
  }
});

test('vatSummary base and vat are integers', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [
    { sku: 'ICON-SET', qty: 1 },
    { sku: 'DES-HOUR', qty: 1 },
  ]);

  const r = vatSummary([invoice]);
  for (const item of r) {
    assert(Number.isInteger(item.base), 'base must be an integer');
    assert(Number.isInteger(item.vat), 'vat must be an integer');
  }
});

test('vatSummary vat is less than or equal to base (typical case)', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 10 }]);

  const r = vatSummary([invoice]);
  for (const item of r) {
    // VAT is typically much less than base (unless VAT rate > 100%, which is rare)
    if (item.rate <= 100) {
      assert(item.vat <= item.base * 1.5, `VAT should be reasonable relative to base`);
    }
  }
});

test('vatSummary with high quantity items', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 100 }]);

  const r = vatSummary([invoice]);
  assert.equal(r.length, 1);
  assert(r[0].base > 100000);
  assert(r[0].vat > 0);
});

test('vatSummary report totals', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);
  const invoice2 = createAndIssueInvoice('C-001', '2025-02-15', [{ sku: 'ICON-SET', qty: 2 }]);

  const r = vatSummary([invoice1, invoice2]);
  const totalBase = r.reduce((sum, item) => sum + item.base, 0);
  const totalVat = r.reduce((sum, item) => sum + item.vat, 0);

  assert(totalBase > 0);
  assert(totalVat > 0);
});

